-- Phase 1, step 1: helper schema and generic triggers.
-- Conventions for every table in this project:
--   * id uuid primary key, generated by the app (works offline) or by the database
--   * shop_id uuid not null on every tenant table, plus unique (shop_id, id) so child tables can use
--     composite foreign keys (shop_id, parent_id). That makes cross-tenant references impossible.
--   * money is bigint in paisas (Rs 1 = 100). Quantities are numeric(14,3).
--   * mutable tables carry updated_at (maintained by app.touch) so phones can sync "changed since".
create schema if not exists app;

create or replace function app.touch() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

-- Blocks UPDATE/DELETE on append-only tables (ledger, stock movements). Corrections are new rows.
create or replace function app.immutable() returns trigger
language plpgsql as $$
begin
  raise exception '% is append-only. Insert a reversing row instead.', tg_table_name using errcode = 'P0001';
end $$;
